"""Triton implementation of aten::_grouped_mm (jagged grouped GEMM).

Contract reproduced from the FlagGems wrapper and the installed pytest:
  self  : (M_total, K)          bf16 rows of G groups packed along M
  mat2  : (G, K, N)             one weight slab per group
  offs  : (G,) int32            exclusive cumulative row ends, offs[-1] == M_total
  out   : (M_total, N)          self.dtype (or out_dtype when given)

out[m, n] = sum_k self[m, k] * mat2[g(m), k, n] (+ bias[g(m), n])

Every output element is produced by exactly one program: no atomics, no reset.
"""

import torch
import triton
import triton.language as tl

# torch ScalarType enum -> dtype, only used if a caller passes an int.
_SCALAR_TYPE_MAP = {
    0: torch.uint8,
    1: torch.int8,
    2: torch.int16,
    3: torch.int32,
    4: torch.int64,
    5: torch.float16,
    6: torch.float32,
    7: torch.float64,
    11: torch.bool,
    15: torch.bfloat16,
}


def _resolve_out_dtype(out_dtype, default):
    if out_dtype is None:
        return default
    if isinstance(out_dtype, torch.dtype):
        return out_dtype
    try:
        mapped = _SCALAR_TYPE_MAP.get(int(out_dtype))
    except (TypeError, ValueError):
        mapped = None
    return mapped if mapped is not None else default


def _pow2_ge(n):
    p = 1
    while p < n:
        p <<= 1
    return p


def _select_config(k, n):
    """Fixed launch configuration; tuned later from measured evidence."""
    return {
        "BLOCK_M": 64,
        "BLOCK_N": 128,
        "BLOCK_K": 64,
        "GROUP_M": 8,
        "num_warps": 8,
        "num_stages": 3,
    }


@triton.jit
def _grouped_mm_jagged_kernel(
    A,
    B,
    C,
    Bias,
    offs,
    stride_am: tl.constexpr,
    stride_ak: tl.constexpr,
    stride_bg: tl.constexpr,
    stride_bk: tl.constexpr,
    stride_bn: tl.constexpr,
    stride_cm: tl.constexpr,
    stride_cn: tl.constexpr,
    stride_bias_g: tl.constexpr,
    N: tl.constexpr,
    K: tl.constexpr,
    NUM_GROUPS: tl.constexpr,
    NUM_N_TILES: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_M: tl.constexpr,
    BLOCK_G: tl.constexpr,
    HAS_BIAS: tl.constexpr,
    EVEN_K: tl.constexpr,
):
    pid = tl.program_id(0)

    # ---- resolve the (group, row-tile, col-tile) triple from the flat pid ----
    # Per-group tile counts are derived from offs inside the kernel: no host
    # read of offs, no device-to-host sync in the timed call.
    gi = tl.arange(0, BLOCK_G)
    gmask = gi < NUM_GROUPS
    ends = tl.load(offs + gi, mask=gmask, other=0).to(tl.int64)
    prev = tl.load(offs + gi - 1, mask=(gi > 0) & gmask, other=0).to(tl.int64)
    starts = tl.where(gi == 0, tl.zeros((BLOCK_G,), dtype=tl.int64), prev)
    sizes = tl.maximum(tl.where(gmask, ends - starts, 0), 0)
    row_tiles = (sizes + (BLOCK_M - 1)) // BLOCK_M
    tiles = row_tiles * NUM_N_TILES
    prefix = tl.cumsum(tiles, axis=0) - tiles
    total = tl.sum(tiles, axis=0)
    if pid >= total:
        return
    g = tl.sum((prefix <= pid).to(tl.int32), axis=0) - 1
    sel = gi == g
    rt = tl.sum(tl.where(sel, row_tiles, 0), axis=0)
    p_g = tl.sum(tl.where(sel, prefix, 0), axis=0)
    s_g = tl.sum(tl.where(sel, starts, 0), axis=0)
    e_g = tl.sum(tl.where(sel, ends, 0), axis=0)

    # Row tiles are swizzled in GROUP_M-row super-groups so that one A
    # super-group stays resident in L2 while all N tiles stream past.
    local = pid - p_g
    width = GROUP_M * NUM_N_TILES
    grp = local // width
    gsize = tl.minimum(rt - grp * GROUP_M, GROUP_M)
    pid_m = grp * GROUP_M + (local % gsize)
    pid_n = (local % width) // gsize

    rows = s_g + pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    row_ok = rows < e_g
    cols = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    cols = tl.max_contiguous(tl.multiple_of(cols, BLOCK_N), BLOCK_N)
    col_ok = cols < N

    ka = tl.arange(0, BLOCK_K)
    a_ptrs = A + rows[:, None] * stride_am + ka[None, :] * stride_ak
    b_ptrs = (
        B
        + g.to(tl.int64) * stride_bg
        + ka[:, None] * stride_bk
        + cols[None, :] * stride_bn
    )

    if EVEN_K:
        a_mask = row_ok[:, None]
        b_mask = col_ok[None, :]
    else:
        k_ok = ka < K
        a_mask = row_ok[:, None] & k_ok[None, :]
        b_mask = k_ok[:, None] & col_ok[None, :]

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for _ in range(0, K, BLOCK_K):
        a = tl.load(a_ptrs, mask=a_mask, other=0.0)
        b = tl.load(b_ptrs, mask=b_mask, other=0.0)
        acc = tl.dot(a, b, acc)
        a_ptrs += BLOCK_K * stride_ak
        b_ptrs += BLOCK_K * stride_bk

    if HAS_BIAS:
        bias_vals = tl.load(
            Bias + g.to(tl.int64) * stride_bias_g + cols, mask=col_ok, other=0.0
        ).to(tl.float32)
        acc += bias_vals[None, :]

    c_ptrs = C + rows[:, None] * stride_cm + cols[None, :] * stride_cn
    c_mask = row_ok[:, None] & col_ok[None, :]
    tl.store(c_ptrs, acc.to(C.dtype.element_ty), mask=c_mask)


def _bias_stride(bias):
    if bias is None:
        return 0
    if bias.dim() == 1:
        return 0
    return bias.stride(0)


def group_mm(self, mat2, offs=None, bias=None, out_dtype=None):
    A = self
    if not torch.is_tensor(A) or not torch.is_tensor(mat2):
        raise TypeError("group_mm expects tensor inputs")
    if A.dim() != 2 or mat2.dim() != 3:
        raise AssertionError("group_mm expects 2D self and 3D mat2")
    if offs is None or not torch.is_tensor(offs):
        raise AssertionError("group_mm expects an offsets tensor")
    if offs.numel() != mat2.shape[0]:
        raise AssertionError("offs length must equal the number of groups")

    M, K = A.shape
    G, K2, N = mat2.shape
    if K2 != K:
        raise AssertionError("mat2 contraction dim must match self")

    cfg = _select_config(K, N)
    block_m = cfg["BLOCK_M"]
    block_n = cfg["BLOCK_N"]
    block_k = cfg["BLOCK_K"]

    dtype = _resolve_out_dtype(out_dtype, A.dtype)
    C = torch.empty((M, N), device=A.device, dtype=dtype)

    num_n_tiles = triton.cdiv(N, block_n)
    grid = ((triton.cdiv(M, block_m) + G) * num_n_tiles,)
    _grouped_mm_jagged_kernel[grid](
        A,
        mat2,
        C,
        C if bias is None else bias,
        offs,
        stride_am=A.stride(0),
        stride_ak=A.stride(1),
        stride_bg=mat2.stride(0),
        stride_bk=mat2.stride(1),
        stride_bn=mat2.stride(2),
        stride_cm=C.stride(0),
        stride_cn=C.stride(1),
        stride_bias_g=_bias_stride(bias),
        N=N,
        K=K,
        NUM_GROUPS=G,
        NUM_N_TILES=num_n_tiles,
        BLOCK_M=block_m,
        BLOCK_N=block_n,
        BLOCK_K=block_k,
        GROUP_M=cfg["GROUP_M"],
        BLOCK_G=_pow2_ge(G),
        HAS_BIAS=bias is not None,
        EVEN_K=(K % block_k == 0),
        num_warps=cfg["num_warps"],
        num_stages=cfg["num_stages"],
    )
    return C
